import type { ChatAdapter } from '../types';

function wait(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    signal.throwIfAborted();
    const abort = () => {
      clearTimeout(timer);
      reject(signal.reason);
    };
    const timer = setTimeout(() => {
      signal.removeEventListener('abort', abort);
      resolve();
    }, ms);
    signal.addEventListener('abort', abort, { once: true });
  });
}

/** Experimental demo adapter: echoes the last user's text, with abortable delays (default 100 ms).
 * @experimental
 */
export function createEchoAdapter({ delayMs = 100 }: { delayMs?: number } = {}): ChatAdapter {
  return {
    async sendMessage({ messages, signal }) {
      const text =
        [...messages]
          .reverse()
          .find((m) => m.role === 'user')
          ?.parts.filter((p) => p.type === 'text')
          .map((p) => p.text)
          .join('') ?? '';
      return (async function* () {
        await wait(delayMs, signal);
        yield { type: 'start' };
        await wait(delayMs, signal);
        yield { type: 'text-delta', id: 'echo', delta: text };
        await wait(delayMs, signal);
        yield { type: 'finish' };
      })();
    },
  };
}

import { readSSE } from '../../read-sse';
import type { ChatAdapter, ChatChunk } from '../types';

/** Backend POST options. url must point to your product backend; keep provider keys server-side.
 * @experimental
 */
export interface HttpChatAdapterOptions {
  url: string;
  headers?: HeadersInit;
  body?: Record<string, unknown>;
  fetch?: typeof globalThis.fetch;
}

export async function postChat(options: HttpChatAdapterOptions, body: Record<string, unknown>, signal: AbortSignal) {
  const headers = new Headers(options.headers);
  headers.set('Content-Type', 'application/json');
  const response = await (options.fetch ?? globalThis.fetch)(options.url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
    signal,
  });
  if (!response.ok) throw new Error(`Chat request failed: HTTP ${response.status}`);
  return response;
}

/** Experimental UI-message-stream v1 adapter. url must be the product backend, with keys on the server.
 * @experimental
 */
export function createHttpChatAdapter(options: HttpChatAdapterOptions): ChatAdapter {
  return {
    async sendMessage({ messages, trigger, signal }) {
      const response = await postChat(options, { ...options.body, messages, trigger }, signal);
      return (async function* (): AsyncGenerator<ChatChunk> {
        for await (const event of readSSE(response, { signal })) {
          if (event.data === '[DONE]') break;
          const chunk: unknown = JSON.parse(event.data);
          if (typeof chunk !== 'object' || chunk === null || !('type' in chunk) || typeof chunk.type !== 'string')
            throw new TypeError('Invalid chat chunk');
          yield chunk as ChatChunk;
        }
      })();
    },
  };
}

import { readSSE } from '../../read-sse';
import type { ChatAdapter, ChatChunk } from '../types';
import { postChat, type HttpChatAdapterOptions } from './http';

/** Options for a text-only chat-completions proxy. Provider keys must stay on the product server.
 * @experimental
 */
export interface OpenAICompatibleAdapterOptions extends HttpChatAdapterOptions {
  model?: string;
}
const record = (value: unknown): Record<string, unknown> =>
  typeof value === 'object' && value !== null ? (value as Record<string, unknown>) : {};

/**
 * Experimental chat-completions SSE adapter. url must be the product backend. Maps content and
 * reasoning_content from the first choice; use the HTTP adapter for files, sources and tool parts.

 * @experimental
 */
export function createOpenAICompatibleAdapter(options: OpenAICompatibleAdapterOptions): ChatAdapter {
  return {
    async sendMessage({ messages, signal }) {
      const response = await postChat(
        options,
        {
          ...(options.model === undefined ? {} : { model: options.model }),
          ...options.body,
          stream: true,
          messages: messages.map((message) => ({
            role: message.role,
            content: message.parts
              .filter((p) => p.type === 'text')
              .map((p) => p.text)
              .join(''),
          })),
        },
        signal,
      );
      return (async function* (): AsyncGenerator<ChatChunk> {
        for await (const event of readSSE(response, { signal })) {
          if (event.data === '[DONE]') break;
          const data = record(JSON.parse(event.data));
          if (data.error) throw new Error(String(record(data.error).message ?? data.error));
          const choice = Array.isArray(data.choices) ? record(data.choices[0]) : {};
          const delta = record(choice.delta);
          if (typeof delta.reasoning_content === 'string')
            yield { type: 'reasoning-delta', id: 'reasoning', delta: delta.reasoning_content };
          if (typeof delta.content === 'string') yield { type: 'text-delta', id: 'text', delta: delta.content };
        }
        yield { type: 'finish' };
      })();
    },
  };
}

import type { ChatChunk, ChatMessagePart, ChatThreadMessage } from './types';

/** Experimental pure UI-stream reducer. Unknown chunk types leave the message unchanged.
 * @experimental
 */
export function applyChunk(message: ChatThreadMessage, chunk: ChatChunk): ChatThreadMessage {
  const c = chunk as { type: string; [key: string]: unknown };
  if (c.type === 'start') return { ...message, status: 'streaming' };
  if (
    ['text-start', 'text-delta', 'reasoning-start', 'reasoning-delta', 'reasoning-end'].includes(c.type) &&
    typeof c.id === 'string'
  ) {
    const id = c.id;
    const type = c.type.startsWith('reasoning') ? 'reasoning' : 'text';
    const delta = typeof c.delta === 'string' ? c.delta : '';
    const state: 'done' | 'streaming' = c.type === 'reasoning-end' ? 'done' : 'streaming';
    const exists = message.parts.some((p) => p.type === type && p.id === id);
    const part: ChatMessagePart = type === 'text' ? { type, id, text: delta } : { type, id, text: delta, state };
    const parts = exists
      ? message.parts.map((p) => {
          if ((p.type !== 'text' && p.type !== 'reasoning') || p.id !== id || p.type !== type) return p;
          return p.type === 'reasoning' ? { ...p, text: p.text + delta, state } : { ...p, text: p.text + delta };
        })
      : [...message.parts, part];
    return { ...message, parts };
  }
  if (
    ['tool-input-available', 'tool-output-available', 'tool-output-error'].includes(c.type) &&
    typeof c.toolCallId === 'string'
  ) {
    const existing = message.parts.find((p) => p.type === 'tool' && p.toolCallId === c.toolCallId);
    const part: Extract<ChatMessagePart, { type: 'tool' }> =
      existing?.type === 'tool'
        ? { ...existing }
        : {
            type: 'tool',
            toolCallId: c.toolCallId,
            toolName: typeof c.toolName === 'string' ? c.toolName : c.toolCallId,
            status: 'running',
          };
    if (c.type === 'tool-input-available') {
      part.toolName = typeof c.toolName === 'string' ? c.toolName : part.toolName;
      part.input = c.input;
      part.status = 'running';
    } else if (c.type === 'tool-output-available') {
      part.output = c.output;
      part.status = 'succeeded';
    } else {
      part.errorText = typeof c.errorText === 'string' ? c.errorText : undefined;
      part.status = 'failed';
    }
    return {
      ...message,
      parts: existing ? message.parts.map((p) => (p === existing ? part : p)) : [...message.parts, part],
    };
  }
  if (c.type === 'source-url' && typeof c.sourceId === 'string' && typeof c.url === 'string') {
    if (message.parts.some((p) => p.type === 'source' && p.id === c.sourceId)) return message;
    return {
      ...message,
      parts: [
        ...message.parts,
        {
          type: 'source',
          id: c.sourceId,
          source: { title: typeof c.title === 'string' ? c.title : c.url, url: c.url },
        },
      ],
    };
  }
  if (c.type === 'file' && typeof c.url === 'string') {
    return {
      ...message,
      parts: [
        ...message.parts,
        {
          type: 'file',
          file: {
            id: c.url,
            name: typeof c.filename === 'string' ? c.filename : c.url,
            type: typeof c.mediaType === 'string' ? c.mediaType : undefined,
            previewUrl: c.url,
          },
        },
      ],
    };
  }
  if (c.type === 'start-step' || c.type === 'finish-step')
    return {
      ...message,
      parts: [...message.parts, { type: 'step', state: c.type === 'start-step' ? 'start' : 'finish' }],
    };
  if (c.type === 'finish')
    return {
      ...message,
      status: 'done',
      parts: message.parts.map((p) => (p.type === 'reasoning' ? { ...p, state: 'done' } : p)),
    };
  if (c.type === 'error')
    return { ...message, status: 'error', error: typeof c.errorText === 'string' ? c.errorText : '' };
  if (c.type === 'abort')
    return {
      ...message,
      status: 'aborted',
      parts: message.parts.map((p) => (p.type === 'tool' && p.status === 'running' ? { ...p, status: 'failed' } : p)),
    };
  return message;
}

import type { ChatChunk } from './types';

/** Cancels readers and detaches stalled iterators even when a custom adapter ignores its signal. */
export async function* chunksFrom(
  source: ReadableStream<ChatChunk> | AsyncIterable<ChatChunk>,
  signal: AbortSignal,
): AsyncGenerator<ChatChunk> {
  const reader = 'getReader' in source ? source.getReader() : undefined;
  const iterator = reader ? undefined : (source as AsyncIterable<ChatChunk>)[Symbol.asyncIterator]();
  let abort: () => void = () => {};
  const aborted = new Promise<never>((_, reject) => {
    abort = () => reject(signal.reason);
    signal.addEventListener('abort', abort, { once: true });
  });
  // An already aborted signal must still have its rejection observed by the race.
  if (signal.aborted) abort();
  let completed = false;
  try {
    while (true) {
      const result = await Promise.race([reader ? reader.read() : iterator!.next(), aborted]);
      if (result.done) {
        completed = true;
        return;
      }
      signal.throwIfAborted();
      yield result.value;
    }
  } finally {
    signal.removeEventListener('abort', abort);
    if (reader) {
      if (!completed) await reader.cancel().catch(() => {});
      reader.releaseLock();
    } else if (!completed) {
      void iterator?.return?.().catch(() => {});
    }
  }
}

export { useChat } from './useChat';
export { applyChunk } from './applyChunk';
export type {
  ChatAdapter,
  ChatChunk,
  KnownChatChunk,
  ChatMessagePart,
  ChatThreadMessage,
  UseChatOptions,
} from './types';
export { createEchoAdapter } from './adapters/echo';
export { createHttpChatAdapter, type HttpChatAdapterOptions } from './adapters/http';
export { createOpenAICompatibleAdapter, type OpenAICompatibleAdapterOptions } from './adapters/openai-compatible';
export { doc as useChatDoc } from './useChat.doc';

import type { ChatAttachment } from '../attachment';
import type { CitationSource } from '../citation';
import type { ToolCallStatus } from '../tool-call-card';

/** Experimental runtime parts, rendered with the existing chat components.
 * @experimental
 */
export type ChatMessagePart =
  | { type: 'text'; id: string; text: string }
  | { type: 'reasoning'; id: string; text: string; state: 'streaming' | 'done' }
  | {
      type: 'tool';
      toolCallId: string;
      toolName: string;
      input?: unknown;
      output?: unknown;
      errorText?: string;
      status: ToolCallStatus;
    }
  | { type: 'source'; id: string; source: CitationSource }
  | { type: 'file'; file: ChatAttachment }
  | { type: 'step'; state: 'start' | 'finish' };

/** Experimental conversation model. Dates are local objects; deserialize persisted dates before use.
 * @experimental
 */
export interface ChatThreadMessage {
  id: string;
  role: 'user' | 'assistant' | 'system';
  parts: ChatMessagePart[];
  status: 'pending' | 'streaming' | 'done' | 'error' | 'aborted';
  error?: string;
  createdAt: Date;
  metadata?: Record<string, unknown>;
}

/** Known UI-message-stream v1 chunks. Unknown types are accepted for forward compatibility.
 * @experimental
 */
export type KnownChatChunk =
  | { type: 'start'; messageId?: string }
  | { type: 'text-start' | 'text-end' | 'reasoning-start' | 'reasoning-end'; id: string }
  | { type: 'text-delta' | 'reasoning-delta'; id: string; delta: string }
  | { type: 'tool-input-available'; toolCallId: string; toolName: string; input: unknown }
  | { type: 'tool-output-available'; toolCallId: string; output: unknown }
  | { type: 'tool-output-error'; toolCallId: string; errorText: string }
  | { type: 'source-url'; sourceId: string; url: string; title?: string }
  | { type: 'file'; url: string; mediaType: string; filename?: string }
  | { type: 'start-step' | 'finish-step' | 'finish' | 'abort' }
  | { type: 'error'; errorText: string };
export type ChatChunk = KnownChatChunk | { type: string; [key: string]: unknown };

/** Experimental backend contract. Provider keys belong on the product server.
 * @experimental
 */
export interface ChatAdapter {
  sendMessage(options: {
    messages: ChatThreadMessage[];
    trigger: 'submit' | 'regenerate';
    signal: AbortSignal;
  }): Promise<ReadableStream<ChatChunk> | AsyncIterable<ChatChunk>>;
  listMessages?(options: {
    cursor: string | null;
    signal: AbortSignal;
  }): Promise<{ messages: ChatThreadMessage[]; nextCursor: string | null }>;
  stop?(options: { messageId: string }): Promise<void>;
}

/** Experimental hook configuration. A changed id aborts both requests and resets the conversation.
 * @experimental
 */
export interface UseChatOptions {
  adapter: ChatAdapter;
  id?: string;
  initialMessages?: ChatThreadMessage[];
  initialCursor?: string | null;
  /** State commits during streaming; default 50 ms. Zero commits every chunk.
   * @experimental
   */
  flushIntervalMs?: number;
  generateId?: () => string;
  onFinish?: (message: ChatThreadMessage) => void;
  onError?: (error: Error, message: ChatThreadMessage) => void;
}

import { useEffect, useRef, useState } from 'react';
import type { ChatAttachment } from '../attachment';
import { applyChunk } from './applyChunk';
import { chunksFrom } from './chunkSource';
import type { ChatAdapter, ChatThreadMessage, UseChatOptions } from './types';

interface Request {
  controller: AbortController;
  adapter: ChatAdapter;
  reply: ChatThreadMessage;
  timer?: ReturnType<typeof setTimeout>;
}

/**
 * Experimental streaming conversation runtime. Adapters call the product backend, never a provider
 * with browser-held keys. Busy sends are ignored. Render parts with the existing chat components;
 * pending/streaming map to ChatMessage.streaming and terminal replies can supply onRetry.
 * @experimental
 */
export function useChat(options: UseChatOptions) {
  const [messages, commitMessages] = useState<ChatThreadMessage[]>(options.initialMessages ?? []);
  const [isStreaming, setStreaming] = useState(false);
  const [error, setError] = useState<Error>();
  const current = useRef(messages);
  const active = useRef<Request | undefined>(undefined);
  const mounted = useRef(true);
  const [hasOlder, setHasOlder] = useState(Boolean(options.adapter.listMessages));
  const [isLoadingOlder, setLoadingOlder] = useState(false);
  const cursor = useRef(options.initialCursor ?? null);
  const older = useRef<AbortController | undefined>(undefined);
  const canLoad = useRef(Boolean(options.adapter.listMessages));
  const latest = useRef(options);
  useEffect(() => {
    latest.current = options;
  });

  useEffect(() => {
    mounted.current = true;
    const initial = latest.current;
    current.current = initial.initialMessages ?? [];
    cursor.current = initial.initialCursor ?? null;
    canLoad.current = Boolean(initial.adapter.listMessages);
    // Reset only when the conversation id changes, never when an inline adapter is re-created.
    commitMessages(current.current);
    setStreaming(false);
    setError(undefined);
    setLoadingOlder(false);
    setHasOlder(canLoad.current);
    return () => {
      mounted.current = false;
      const request = active.current;
      active.current = undefined;
      older.current?.abort();
      older.current = undefined;
      if (request) {
        clearTimeout(request.timer);
        request.controller.abort();
        void request.adapter.stop?.({ messageId: request.reply.id }).catch(() => {});
      }
    };
  }, [options.id]);

  const publish = () => {
    if (mounted.current) commitMessages([...current.current]);
  };
  const update = (request: Request) => {
    current.current = current.current.map((m) => (m.id === request.reply.id ? request.reply : m));
  };
  const begin = (history: ChatThreadMessage[], trigger: 'submit' | 'regenerate') => {
    const reply: ChatThreadMessage = {
      id: options.generateId?.() ?? crypto.randomUUID(),
      role: 'assistant',
      parts: [],
      status: 'pending',
      createdAt: new Date(),
    };
    const request: Request = { controller: new AbortController(), reply, adapter: options.adapter };
    active.current = request;
    current.current = [...history, reply];
    publish();
    setStreaming(true);
    setError(undefined);
    const valid = () => mounted.current && active.current === request;
    const finish = () => {
      clearTimeout(request.timer);
      update(request);
      publish();
      active.current = undefined;
      setStreaming(false);
    };
    void (async () => {
      try {
        const source = await options.adapter.sendMessage({
          messages: history,
          trigger,
          signal: request.controller.signal,
        });
        for await (const chunk of chunksFrom(source, request.controller.signal)) {
          if (!valid()) return;
          request.reply = applyChunk({ ...request.reply, status: 'streaming' }, chunk);
          if (request.reply.status === 'error') throw new Error(request.reply.error);
          update(request);
          if (request.reply.status === 'done' || request.reply.status === 'aborted') break;
          if (options.flushIntervalMs === 0) publish();
          else if (request.timer === undefined)
            request.timer = setTimeout(() => {
              request.timer = undefined;
              if (valid()) publish();
            }, options.flushIntervalMs ?? 50);
        }
        if (!valid()) return;
        if (request.reply.status !== 'aborted') request.reply = applyChunk(request.reply, { type: 'finish' });
        finish();
        if (request.reply.status === 'done') options.onFinish?.(request.reply);
      } catch (cause) {
        if (!valid()) return;
        const failure = cause instanceof Error ? cause : new Error(String(cause));
        request.reply = { ...request.reply, status: 'error', error: failure.message };
        finish();
        setError(failure);
        options.onError?.(failure, request.reply);
      }
    })();
  };
  const sendMessage = (text: string, attachments: ChatAttachment[] = []) => {
    if (active.current || !mounted.current) return;
    const user: ChatThreadMessage = {
      id: options.generateId?.() ?? crypto.randomUUID(),
      role: 'user',
      status: 'done',
      createdAt: new Date(),
      parts: [{ type: 'text', id: 'text', text }, ...attachments.map((file) => ({ type: 'file' as const, file }))],
    };
    begin([...current.current, user], 'submit');
  };

  const stop = () => {
    const request = active.current;
    if (!request) return;
    active.current = undefined;
    clearTimeout(request.timer);
    request.controller.abort();
    request.reply = applyChunk(request.reply, { type: 'abort' });
    update(request);
    publish();
    setStreaming(false);
    void request.adapter.stop?.({ messageId: request.reply.id }).catch(() => {});
  };
  const regenerate = (messageId?: string) => {
    if (active.current || !mounted.current) return;
    const index =
      messageId === undefined
        ? current.current.reduce((last, m, i) => (m.role === 'assistant' ? i : last), -1)
        : current.current.findIndex((m) => m.id === messageId && m.role === 'assistant');
    if (index < 0) return;
    begin(current.current.slice(0, index), 'regenerate');
  };
  const setMessages = (next: ChatThreadMessage[] | ((previous: ChatThreadMessage[]) => ChatThreadMessage[])) => {
    if (!mounted.current) return;
    current.current = typeof next === 'function' ? next(current.current) : next;
    publish();
  };
  const loadOlder = async () => {
    if (!mounted.current || older.current || !canLoad.current || !options.adapter.listMessages) return;
    const controller = new AbortController();
    older.current = controller;
    setLoadingOlder(true);
    try {
      const page = await options.adapter.listMessages({ cursor: cursor.current, signal: controller.signal });
      if (!mounted.current || older.current !== controller) return;
      current.current = [...page.messages, ...current.current];
      cursor.current = page.nextCursor;
      canLoad.current = page.nextCursor !== null;
      setHasOlder(canLoad.current);
      publish();
    } catch (cause) {
      if (mounted.current && older.current === controller)
        setError(cause instanceof Error ? cause : new Error(String(cause)));
    } finally {
      if (mounted.current && older.current === controller) {
        older.current = undefined;
        setLoadingOlder(false);
      }
    }
  };
  return {
    messages,
    isStreaming,
    error,
    sendMessage,
    stop,
    regenerate,
    setMessages,
    loadOlder,
    hasOlder,
    isLoadingOlder,
  };
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'useChat',
  group: 'Feedback',
  status: 'experimental',
  description:
    'Experimental streaming conversation runtime: useChat({ adapter, id, initialMessages, initialCursor, flushIntervalMs, generateId, onFinish, onError }) returns messages, isStreaming, error, sendMessage(text, attachments?), stop(), regenerate(messageId?), setMessages(next), loadOlder(), hasOlder and isLoadingOlder. Busy sends are ignored. Messages hold text, reasoning, tool, source, file and step parts. applyChunk is a pure UI-message-stream v1 reducer; unknown chunk types are ignored. Stop and unmount abort the adapter signal and retain partial parts; failed replies call onError once. State updates batch every 50 ms (0 commits every chunk). A changed conversation id aborts and resets. createEchoAdapter runs locally; createHttpChatAdapter reads UI-stream SSE and createOpenAICompatibleAdapter maps text-only chat-completions SSE. Both reuse readSSE and check HTTP status first. Their URL must be the product backend: provider keys stay server-side. Map pending/streaming to ChatMessage.streaming, and terminal replies to onRetry; ChatMessage has no status prop. See the chat runtime guide on this page for the protocol, history, abort and part mapping.',
};
